    ["Cyber Engine Tweaks writes cyber_engine_tweaks.log and scripting.log in {path}"] = "Cyber Engine Tweaks schreibt cyber_engine_tweaks.log und scripting.log in {path}",
    ["Find the log files and create a report to send to the developer if something goes wrong."] = "Hier findest du die Protokolldateien und kannst einen Bericht für den Entwickler erstellen, falls etwas schiefgeht.",
    ["Generate report"] = "Bericht erzeugen",
