    ["Report saved: {path}"] = "Bericht gespeichert: {path}",
    ["Running"] = "Läuft",
    ["Save a report file you can send to the developer. API keys, tokens, IDs, microphone audio and conversation text are left out. If the conversation service is not running, a shorter report is made from the files the game can read."] = "Speichere eine Berichtsdatei, die du an den Entwickler senden kannst. API-Schlüssel, Tokens, IDs, Mikrofonaudio und Gesprächstext werden weggelassen. Läuft der Gesprächsdienst nicht, wird aus den Dateien, die das Spiel lesen kann, ein kürzerer Bericht erstellt.",
    ["Saved at {path}"] = "Gespeichert unter {path}",
    ["Saved reports"] = "Gespeicherte Berichte",
    ["Send the generated report rather than raw log files. Open these locations only if the developer asks for a specific file."] = "Sende den erzeugten Bericht statt roher Protokolldateien. Öffne diese Orte nur, wenn der Entwickler nach einer bestimmten Datei fragt.",
    ["Short report saved because the conversation service could not build the full report: {path}"] = "Kurzbericht gespeichert, weil der Gesprächsdienst den vollständigen Bericht nicht erstellen konnte: {path}",
    ["Short report saved because the conversation service did not answer: {path}"] = "Kurzbericht gespeichert, weil der Gesprächsdienst nicht geantwortet hat: {path}",
    ["Short report saved because the conversation service is not running: {path}"] = "Kurzbericht gespeichert, weil der Gesprächsdienst nicht läuft: {path}",
    ["Starting"] = "Startet",
    ["Support report saved: {path}"] = "Support-Bericht gespeichert: {path}",
    ["The clipboard is not available here. Read the path from the Last report row."] = "Die Zwischenablage ist hier nicht verfügbar. Lies den Pfad in der Zeile Letzter Bericht ab.",
    ["The conversation service runs beside the game. If it is not running, restart the game. Its logs are listed below."] = "Der Gesprächsdienst läuft neben dem Spiel. Läuft er nicht, starte das Spiel neu. Seine Protokolle sind unten aufgeführt.",
    ["The conversation service writes bridge.stderr.log, bridge.stdout.log and bridge-service.log in {path}"] = "Der Gesprächsdienst schreibt bridge.stderr.log, bridge.stdout.log und bridge-service.log in {path}",
    ["The redscript compiler writes redscript_rCURRENT.log at {path}"] = "Der Redscript-Compiler schreibt redscript_rCURRENT.log in {path}",
    ["The report could not be created. Check that the mod folder can be written to, then try again."] = "Der Bericht konnte nicht erstellt werden. Prüfe, ob in den Mod-Ordner geschrieben werden kann, und versuche es dann erneut.",
    ["The service launcher writes launcher.log at {path}"] = "Der Dienststarter schreibt launcher.log in {path}",
    ["This is a short report: the conversation service was not available to build the full one."] = "Dies ist ein Kurzbericht: Der Gesprächsdienst war nicht verfügbar, um den vollständigen Bericht zu erstellen.",
    ["Unknown"] = "Unbekannt",
    ["What to do"] = "Was zu tun ist",
    ["Where the logs are"] = "Wo die Protokolle liegen",
    ["the game folder"] = "der Spielordner",
    ["the runtime folder of the mod project, or the data folder inside the mod folder"] = "der Runtime-Ordner des Mod-Projekts oder der Datenordner im Mod-Ordner",
    ["Auto-connect nearby characters"] = "Figuren in der Nähe automatisch verbinden",
    ["Continue from game dialogue"] = "An Spieldialoge anknüpfen",
    ["When you talk to a character right after the game’s own dialogue with them, they know the last few lines that were just said, including your chosen replies and phone calls with them, so their answer follows on naturally. Only lines from the last few minutes that involved that character are used, and they are not added to the character’s memory. On by default."] = "Wenn du direkt nach einem Spieldialog mit einer Figur mit ihr sprichst, kennt sie die letzten gerade gesagten Zeilen, einschließlich deiner gewählten Antworten und Telefonate mit ihr, sodass ihre Antwort natürlich daran anknüpft. Verwendet werden nur Zeilen aus den letzten Minuten, an denen diese Figur beteiligt war; sie werden nicht in das Gedächtnis der Figur aufgenommen. Standardmäßig an.",
    ["Preparing connection to {name}…"] = "Verbindung zu {name} wird vorbereitet…",
    ["{names} joined your group."] = "{names} sind deiner Gruppe beigetreten.",
    ["{first} and {second}"] = "{first} und {second}",
    ["{first}, {second} and {third}"] = "{first}, {second} und {third}",
    ["{first}, {second} and {count} others"] = "{first}, {second} und {count} weitere",
    ["{count} more companions also failed."] = "{count} weitere Begleiter sind ebenfalls fehlgeschlagen.",
    ["Change pending. Choose Apply to use it, or Revert to discard it."] = "Änderung ausstehend. Wähle „Übernehmen“, um sie zu verwenden, oder „Zurücksetzen“, um sie zu verwerfen.",
    ["Changes wait until you choose Apply."] = "Änderungen warten, bis du „Übernehmen“ wählst.",
    ["Changes wait until you choose Apply; Revert discards them. No game restart is needed."] = "Änderungen warten, bis du „Übernehmen“ wählst; „Zurücksetzen“ verwirft sie. Ein Spielneustart ist nicht nötig.",
    ["Pending: {voice}"] = "Ausstehend: {voice}",
    ["Natural speech"] = "Natürliche Sprechweise",
    ["Let companions speak the way a real person with their personality would: now and then a pause, a hesitation, a laugh or a sigh. Each character decides when it fits, and it stays rare; a fluent, confident speaker will hardly use it. OmniVoice can voice laughs and sighs; Pocket TTS uses only pauses in the sentence. It needs a local voice: choosing the Convai cloud voice keeps it and turns this off, and turning this on while the cloud voice is saved moves Companion voices to Pocket TTS. Off by default."] = "Lass Begleiter so sprechen, wie es ein echter Mensch mit ihrer Persönlichkeit tun würde: hin und wieder eine Pause, ein Zögern, ein Lachen oder ein Seufzen. Jede Figur entscheidet selbst, wann es passt, und es bleibt selten; wer flüssig und selbstsicher spricht, nutzt es kaum. OmniVoice kann Lachen und Seufzen sprechen; Pocket TTS nutzt nur Pausen im Satz. Es braucht eine lokale Stimme: Wählt man die Convai-Cloud-Stimme, bleibt sie gewählt und es wird ausgeschaltet; wird es eingeschaltet, während die Cloud-Stimme gespeichert ist, wechseln die Begleiterstimmen zu Pocket TTS. Standardmäßig aus.",
    ["Natural speech needs a local voice, so {setting} was switched to {voice}."] = "Natürliche Sprechweise braucht eine lokale Stimme, deshalb wurde {setting} auf {voice} umgestellt.",
    ["Expressive emotions"] = "Ausdrucksstarke Emotionen",
    ["Let each character mark its own feelings as it speaks, so the face changes when that part is spoken instead of being guessed from the words. Subtle by default, chosen by personality, and only where the feeling really shifts. It needs a local voice: choosing the Convai cloud voice keeps it and turns this off, and turning this on while the cloud voice is saved moves Companion voices to Pocket TTS. A reply without marks uses the usual text-based expression. On by default."] = "Lass jede Figur ihre Gefühle beim Sprechen selbst markieren, damit sich das Gesicht genau dann ändert, wenn der Abschnitt gesprochen wird, statt aus den Worten erraten zu werden. Standardmäßig dezent, nach Persönlichkeit gewählt und nur dort, wo sich das Gefühl wirklich ändert. Es braucht eine lokale Stimme: Wählt man die Convai-Cloud-Stimme, bleibt sie gewählt und es wird ausgeschaltet; wird es eingeschaltet, während die Cloud-Stimme gespeichert ist, wechseln die Begleiterstimmen zu Pocket TTS. Eine Antwort ohne Markierungen nutzt den üblichen textbasierten Ausdruck. Standardmäßig an.",
    ["Expressive emotions need a local voice, so {setting} was switched to {voice}."] = "Ausdrucksstarke Emotionen brauchen eine lokale Stimme, deshalb wurde {setting} auf {voice} umgestellt.",
    ["Follow-up questions"] = "Nachfragen",
    ["Characters sometimes show interest in you and keep the conversation going: they ask about something you just said, pick up something from earlier or share a thought that invites an answer. It happens now and then, never on every reply, and never while you are leaving, giving an order or fighting. Works with any voice. On by default."] = "Figuren zeigen manchmal Interesse an dir und halten das Gespräch am Laufen: Sie fragen nach etwas, das du gerade gesagt hast, greifen etwas von früher auf oder teilen einen Gedanken, der zu einer Antwort einlädt. Das passiert hin und wieder, nie bei jeder Antwort und nie, wenn du dich verabschiedest, einen Befehl gibst oder kämpfst. Funktioniert mit jeder Stimme. Standardmäßig an.",
    ["Pocket · Performance"] = "Pocket · Leistung",
    ["OmniVoice · Balanced"] = "OmniVoice · Ausgewogen",
    ["OmniVoice · Quality"] = "OmniVoice · Qualität",
    ["OmniVoice · High Quality"] = "OmniVoice · Hohe Qualität",
    ["OmniVoice · Ultra Quality"] = "OmniVoice · Höchste Qualität",
    ["Convai · Cloud voice"] = "Convai · Cloud-Stimme",
    ["{voice} · needs Omni pack"] = "{voice} · benötigt Omni-Paket",
    ["Subtle"] = "Dezent",
    ["Strong"] = "Stark",
    ["Body gestures (experimental)"] = "Körpergesten (experimentell)",
    ["Romantic"] = "Romantisch",
    ["Casual"] = "Zwanglos",
    ["Ordinary"] = "Gewöhnlich",
    ["Auto follows the completed encounter in this save. Casual lets her speak with that familiarity; Ordinary keeps her usual manner. This does not imply an ongoing relationship."] = "Automatisch richtet sich nach der abgeschlossenen Begegnung in diesem Spielstand. Zwanglos lässt sie mit dieser Vertrautheit sprechen; Gewöhnlich bleibt bei ihrer üblichen Art. Dies bedeutet keine fortbestehende Beziehung.",
    ["Auto follows the relationship in this save. Romantic has them speak to V as a partner; Ordinary keeps their usual manner. This changes conversations without changing game choices."] = "Automatisch richtet sich nach der Beziehung in diesem Spielstand. Romantisch lässt die Figuren V als Partner ansprechen; Gewöhnlich behält deren übliche Art bei. Dies verändert die Gespräche, ohne Spielentscheidungen zu ändern.",
    ["Choose one of the listed relationship options."] = "Wähle eine der angebotenen Beziehungsoptionen.",
    ["For testing and bug reports; leave it off for normal play. It shows routine companion popups (the joining step, dismissal confirmations, driving instructions such as boarding and exit, results of companion actions, and a notice when a support report is ready), writes a movement trace file in the mod’s runtime folder, logs body gesture decisions, and adds this setting to support reports. Preparation progress, joined notices, failures and replies to Stop trip remain visible when off."] = "Zum Testen und für Fehlerberichte; für normales Spielen ausgeschaltet lassen. Zeigt gewöhnliche Begleiter-Meldungen (den Beitrittsschritt, Bestätigungen beim Entlassen, Fahranweisungen wie Ein- und Aussteigen, Ergebnisse von Begleiteraktionen und einen Hinweis, wenn ein Supportbericht bereit ist), schreibt eine Bewegungsprotokolldatei im Laufzeitordner der Mod, protokolliert Entscheidungen zu Körpergesten und fügt diese Einstellung den Supportberichten hinzu. Vorbereitungsfortschritt, Beitrittsmeldungen, Fehler und Rückmeldungen zu Fahrt stoppen bleiben auch bei ausgeschaltetem Modus sichtbar.",
    ["Browse every character model in the game and invite any of them, including characters without conversation support. They join as followers and do not talk."] = "Durchsuche jedes Charaktermodell des Spiels und lade jedes davon ein, auch Charaktere ohne Gesprächsunterstützung. Sie kommen als Begleiter ohne Gespräche dazu und sprechen nicht.",
    ["Every character model found in the game, including characters without conversation support. Those join as followers and do not talk."] = "Jedes im Spiel gefundene Charaktermodell, auch Charaktere ohne Gesprächsunterstützung. Diese kommen als Begleiter dazu und sprechen nicht.",
    ["Above the speaker"] = "Über dem Sprecher",
    ["Cinematic subtitles"] = "Filmische Untertitel",
    ["Cinematic subtitles use the game’s regular dialogue display; Above the speaker places them over the speaking companion. The Subtitles switch controls both."] = "Filmische Untertitel nutzen die normale Dialoganzeige des Spiels; Über dem Sprecher platziert sie über dem sprechenden Begleiter. Der Untertitel-Schalter steuert beide.",
    ["Choose one of the listed subtitle displays."] = "Wähle eine der angebotenen Untertitelanzeigen.",
    ["Multilingual conversations"] = "Mehrsprachige Gespräche",
    ["Pocket is light and fast on your CPU and starts speaking in about 0.2 s. OmniVoice sounds better, especially on harder voices, but needs a capable GPU and the optional OmniVoice pack (without it those entries are marked and cannot be applied), and the higher tiers take longer to start speaking, about 1 to 2.5 s. Convai uses the cloud; if a choice cannot run, a simpler voice takes over and you are told once."] = "Pocket ist schlank und schnell auf deiner CPU und beginnt nach etwa 0,2 s zu sprechen. OmniVoice klingt besser, besonders bei schwierigeren Stimmen, benötigt aber eine leistungsfähige GPU und das optionale OmniVoice-Paket (ohne dieses sind die Einträge markiert und lassen sich nicht anwenden); die höheren Stufen brauchen länger, bis gesprochen wird, etwa 1 bis 2,5 s. Convai nutzt die Cloud; kann eine Auswahl nicht laufen, springt eine einfachere Stimme ein und du wirst einmal informiert.",
    ["Prepares the conversation with a character you look at, walk up to or have just talked to, so they answer without a wait; it pauses during combat and scenes. At most two characters are kept ready at any moment, at most one new connection starts every 3 seconds and a character is released after 40 seconds unused, so a crowd never adds up."] = "Bereitet das Gespräch mit einem Charakter vor, den du ansiehst, dem du dich näherst oder mit dem du gerade gesprochen hast, damit er ohne Wartezeit antwortet; es pausiert bei Kämpfen und Szenen. Höchstens zwei Charaktere sind gleichzeitig bereit, höchstens alle 3 Sekunden wird eine neue Verbindung gestartet und ein Charakter wird nach 40 Sekunden ohne Nutzung freigegeben, sodass sich auch in einer Menschenmenge nichts aufsummiert.",
    ["Raise or lower where companions look when they make eye contact with you."] = "Hebt oder senkt, wohin Begleiter blicken, wenn sie Blickkontakt mit dir aufnehmen.",
    ["Talk to companions in any language: each character answers in the language you use. It uses a multilingual copy of each character, so what they remember from these conversations is kept apart from your English ones; forgetting a character clears both. Pocket TTS speaks only English, so turning this on switches Companion voices to OmniVoice · Balanced when the optional OmniVoice pack is installed, or to Convai · Cloud voice otherwise; without the pack, Natural speech and Expressive emotions are turned off, because the cloud voice would read their tags aloud. Off by default."] = "Sprich mit Begleitern in jeder Sprache: Jeder Charakter antwortet in der Sprache, die du benutzt. Dafür wird eine mehrsprachige Kopie jedes Charakters verwendet, daher werden seine Erinnerungen an diese Gespräche getrennt von denen an deine englischen Gespräche gespeichert; wenn du die Erinnerungen eines Charakters vergisst, werden beide gelöscht. Pocket TTS spricht nur Englisch, daher schaltet das Einschalten dieser Option Begleiterstimmen auf OmniVoice · Ausgewogen um, wenn das optionale OmniVoice-Paket installiert ist, andernfalls auf Convai · Cloud-Stimme; ohne das Paket werden Natürliche Sprechweise und Ausdrucksstarke Emotionen ausgeschaltet, weil die Cloud-Stimme ihre Tags vorlesen würde. Standardmäßig aus.",
    ["Pocket TTS speaks only English. Turn off Multilingual conversations to choose it."] = "Pocket TTS spricht nur Englisch. Schalte Mehrsprachige Gespräche aus, um es auszuwählen.",
    ["Multilingual conversations needs a voice that speaks every language, so {setting} was switched to {voice}."] = "Mehrsprachige Gespräche braucht eine Stimme, die alle Sprachen spricht, deshalb wurde {setting} auf {voice} umgestellt.",
    ["Natural speech and Expressive emotions need the OmniVoice pack while Multilingual conversations is on: the Convai cloud voice would read their tags aloud."] = "Natürliche Sprechweise und Ausdrucksstarke Emotionen brauchen das OmniVoice-Paket, solange Mehrsprachige Gespräche eingeschaltet ist: Die Convai-Cloud-Stimme würde ihre Tags vorlesen.",
    ["Natural speech and Expressive emotions were turned off: the Convai cloud voice would read their tags aloud. With the OmniVoice pack, all three work together."] = "Natürliche Sprechweise und Ausdrucksstarke Emotionen wurden ausgeschaltet: Die Convai-Cloud-Stimme würde ihre Tags vorlesen. Mit dem OmniVoice-Paket funktionieren alle drei zusammen.",
    ["The Convai cloud voice cannot use Natural speech or Expressive emotions, so they were turned off."] = "Die Convai-Cloud-Stimme kann „Natürliche Sprechweise“ und „Ausdrucksstarke Emotionen“ nicht nutzen, deshalb wurden sie ausgeschaltet.",
    ["Voice status"] = "Sprachstatus",
    ["Who can talk"] = "Wer sprechen darf",
    ["That action is not available."] = "Diese Aktion ist nicht verfügbar.",
    ["That companion is no longer in your party."] = "Dieser Begleiter ist nicht mehr in deiner Gruppe.",
    ["{name} can't come along right now."] = "{name} kann gerade nicht mitkommen.",
    ["{name} is already with you."] = "{name} ist bereits bei dir.",
    ["{name} is coming with you."] = "{name} kommt mit dir.",
    ["{name} is leaving your party."] = "{name} verlässt deine Gruppe.",
    ["{name} is no longer nearby."] = "{name} ist nicht mehr in der Nähe.",
    ["{name} · game voice"] = "{name} · Spielstimme",
    ["Play"] = "Abspielen",
    ["Plays one of this character’s own lines from the game, through the game’s normal dialogue audio, so you can compare their companion voice with it. You hear it when you return to gameplay; each press tries another line, and a character may have no line for some of them."] = "Spielt eine der eigenen Zeilen dieser Figur aus dem Spiel über den normalen Dialogton des Spiels ab, damit du ihre Begleiterstimme damit vergleichen kannst. Du hörst sie bei deiner Rückkehr ins Spiel; jeder Druck versucht eine andere Zeile, und für manche hat eine Figur vielleicht keine.",
    ["{name} will say one of their game lines when you return to the game."] = "{name} sagt bei deiner Rückkehr ins Spiel eine eigene Zeile aus dem Spiel.",
    ["Lip sync delay (Bluetooth)"] = "Lippensynchron-Verzögerung (Bluetooth)",
    ["Bluetooth earbuds and headphones play sound a little later than the picture, so lips and subtitles can run slightly ahead of the voice. This holds them back to match, for every voice. Auto uses 150 ms while Windows plays through a Bluetooth device and none otherwise; choose a value if your headset is faster or slower. The game’s own dialogue has the same Bluetooth delay and does not correct it."] = "Bluetooth-Kopfhörer geben den Ton etwas später wieder als das Bild, sodass Lippen und Untertitel der Stimme leicht vorauslaufen können. Dies hält sie passend zurück, für alle Stimmen. Automatisch nutzt 150 ms, solange Windows über ein Bluetooth-Gerät wiedergibt, sonst keine; wähle einen Wert, wenn dein Kopfhörer schneller oder langsamer ist. Die eigenen Dialoge des Spiels haben dieselbe Bluetooth-Verzögerung, und das Spiel gleicht sie nicht aus.",
    ["Choose one of the listed lip sync delays."] = "Wähle eine der angebotenen Lippensynchron-Verzögerungen.",
    ["Behavior: {list}"] = "Verhalten: {list}",
    ["In your party: {count}"] = "In deiner Gruppe: {count}",
    ["Memory: remembers your conversations"] = "Erinnerungen: erinnert sich an eure Gespräche",
    ["Multilingual: replies in your language"] = "Mehrsprachig: antwortet in deiner Sprache",
    ["Relationship: {mode}"] = "Beziehung: {mode}",
    ["Speech: {list}"] = "Sprechweise: {list}",
    ["Added"] = "Hinzugefügt",
    ["Added (ends in {tail})"] = "Hinzugefügt (endet auf {tail})",
    ["Checking…"] = "Wird geprüft…",
    ["Convai API key"] = "Convai-API-Schlüssel",
    ["Convai did not accept that key."] = "Convai hat diesen Schlüssel nicht akzeptiert.",
    ["Convai did not accept your API key. Check it in Settings > Development."] = "Convai hat deinen API-Schlüssel nicht akzeptiert. Prüfe ihn unter Einstellungen > Entwicklung.",
    ["Conversations use"] = "Gespräche nutzen",
    ["You’ve reached today’s free conversation limit. Convai (better quality responses) is back tomorrow. To keep talking now, add a free Mistral key and set Conversation provider to Mistral in Settings > Development. A fully local option is coming."] = "Du hast das heutige kostenlose Gesprächslimit erreicht. Convai (bessere Antwortqualität) ist morgen wieder da. Um jetzt weiterzusprechen, füge einen kostenlosen Mistral-API-Schlüssel hinzu und stelle unter Einstellungen > Entwicklung den Gesprächsanbieter auf Mistral. Eine vollständig lokale Option kommt noch.",
    ["The conversation limit has been reached. Try again later, or add a free Mistral key and set Conversation provider to Mistral in Settings > Development."] = "Das Gesprächslimit wurde erreicht. Versuch es später erneut oder füge einen kostenlosen Mistral-API-Schlüssel hinzu und stelle unter Einstellungen > Entwicklung den Gesprächsanbieter auf Mistral.",
    ["Mistral’s free limit is reached for now. Try again in a moment."] = "Das kostenlose Limit von Mistral ist vorerst erreicht. Versuch es gleich noch einmal.",
    ["Use a Convai API key of your own for conversations. Paste it below, turn this on and choose Apply. The change waits until no conversation is running."] = "Verwende für Gespräche deinen eigenen Convai-API-Schlüssel. Füge ihn unten ein, aktiviere diese Option und wähle Übernehmen. Die Änderung wartet, bis kein Gespräch läuft.",
    ["Copy your key first. It is read from the clipboard once, checked with Convai and saved on this computer."] = "Kopiere zuerst deinen Schlüssel. Er wird einmal aus der Zwischenablage gelesen, bei Convai geprüft und auf diesem Computer gespeichert.",
    ["Deletes the saved key. Conversations go back to the shared plan."] = "Löscht den gespeicherten Schlüssel. Gespräche wechseln zurück zum gemeinsamen Tarif.",
    ["Not added"] = "Nicht hinzugefügt",
    ["Paste Convai API key"] = "Convai-API-Schlüssel einfügen",
    ["Paste from clipboard"] = "Aus der Zwischenablage einfügen",
    ["Remove"] = "Entfernen",
    ["Remove my Convai API key"] = "Meinen Convai-API-Schlüssel entfernen",
    ["Saved on this computer only. Only the last four characters are ever shown."] = "Nur auf diesem Computer gespeichert. Es werden immer nur die letzten vier Zeichen angezeigt.",
    ["Shared plan: daily limit reached"] = "Gemeinsamer Tarif: tägliches Limit erreicht",
    ["Shared plan: limit used up"] = "Gemeinsamer Tarif: Limit aufgebraucht",
    ["The clipboard could not be read."] = "Die Zwischenablage konnte nicht gelesen werden.",
    ["The clipboard does not hold a Convai API key."] = "Die Zwischenablage enthält keinen Convai-API-Schlüssel.",
    ["The clipboard is empty. Copy your key first."] = "Die Zwischenablage ist leer. Kopiere zuerst deinen Schlüssel.",
    ["The key could not be saved."] = "Der Schlüssel konnte nicht gespeichert werden.",
    ["The request could not be sent. Try again."] = "Die Anfrage konnte nicht gesendet werden. Versuche es erneut.",
    ["The shared plan"] = "Der gemeinsame Tarif",
    ["The shared plan: {left} of {limit} left today"] = "Der gemeinsame Tarif: heute noch {left} von {limit} übrig",
    ["Use my own Convai API key"] = "Meinen eigenen Convai-API-Schlüssel verwenden",
    ["Your Convai API key has reached its plan limit. Try again later or add a different key in Settings > Development."] = "Dein Convai-API-Schlüssel hat sein Tarif-Limit erreicht. Versuche es später erneut oder füge unter Einstellungen > Entwicklung einen anderen Schlüssel hinzu.",
    ["Your key was removed."] = "Dein Schlüssel wurde entfernt.",
    ["Your key: not accepted"] = "Dein Schlüssel: nicht akzeptiert",
    ["Your key: plan limit reached"] = "Dein Schlüssel: Tarif-Limit erreicht",
    ["Your own key"] = "Eigener Schlüssel",
    ["Your Convai plan cannot hold the memory these conversations need. Free a memory user in your Convai account or use another key."] = "Dein Convai-Tarif reicht nicht für den Speicher, den diese Gespräche brauchen. Gib in deinem Convai-Konto einen Speicher-Nutzer frei oder verwende einen anderen Schlüssel.",
    ["Your Convai plan has no room for conversation memory, so companions will not remember past talks."] = "Dein Convai-Tarif bietet keinen Platz für Gesprächsspeicher, daher werden sich Begleiter nicht an frühere Gespräche erinnern.",
    ["Your key: no room for memory"] = "Dein Schlüssel: kein Platz für Speicher",
    ["Your own key, without memory"] = "Eigener Schlüssel, ohne Speicher",
    ["Choose one of the listed conversation providers."] = "Wähle einen der aufgelisteten Gesprächsanbieter aus.",
    ["Convai"] = "Convai",
    ["Convai: Mistral has no key yet"] = "Convai: Für Mistral gibt es noch keinen Schlüssel",
    ["Conversation provider"] = "Gesprächsanbieter",
    ["Copy your free key from Mistral first. It is read from the clipboard once, checked with Mistral and saved on this computer. You can also save it in the file player-mistral-key.txt in the conversation service folder."] = "Kopiere zuerst deinen kostenlosen Schlüssel von Mistral. Er wird einmal aus der Zwischenablage gelesen, bei Mistral geprüft und auf diesem Computer gespeichert. Du kannst ihn auch in der Datei player-mistral-key.txt im Ordner des Gesprächsdienstes speichern.",
    ["Deletes the saved key. Conversations go back to Convai."] = "Löscht den gespeicherten Schlüssel. Gespräche kehren zu Convai zurück.",
    ["Mistral (free plan)"] = "Mistral (kostenloser Tarif)",
    ["Mistral did not accept that key."] = "Mistral hat diesen Schlüssel nicht akzeptiert.",
    ["Mistral did not accept your key. Check it in Settings > Development."] = "Mistral hat deinen Schlüssel nicht akzeptiert. Prüfe ihn unter Einstellungen > Entwicklung.",
    ["Mistral has no key yet, so Convai is used. Add your key in Settings > Development."] = "Für Mistral gibt es noch keinen Schlüssel, daher wird Convai verwendet. Füge deinen Schlüssel unter Einstellungen > Entwicklung hinzu.",
    ["Mistral key"] = "Mistral-API-Schlüssel",
    ["Mistral replies are spoken by a local voice instead of the Convai cloud voice."] = "Mistral-Antworten werden von einer lokalen Stimme gesprochen statt der Convai-Cloud-Stimme.",
    ["Mistral: free limit reached for now"] = "Mistral: Kostenloses Limit vorerst erreicht",
    ["Mistral: key not accepted"] = "Mistral: Schlüssel nicht akzeptiert",
    ["Mistral: model unavailable"] = "Mistral: Modell nicht verfügbar",
    ["Paste Mistral key"] = "Mistral-API-Schlüssel einfügen",
    ["Remove my Mistral key"] = "Meinen Mistral-API-Schlüssel entfernen",
    ["Speaking to companions needs Convai for now. Set Conversation provider to Convai in Settings > Development, or type your message."] = "Mit Begleitern zu sprechen braucht vorerst Convai. Stelle unter Einstellungen > Entwicklung den Gesprächsanbieter auf Convai ein, oder tippe deine Nachricht ein.",
    ["The Mistral model is unavailable right now. Try again in a minute."] = "Das Mistral-Modell ist gerade nicht verfügbar. Versuch es in einer Minute erneut.",
    ["Waiting for the conversation to end"] = "Warten, bis das Gespräch endet",
    ["Which provider answers your conversations right now and, for Convai, which plan pays for them. Changes wait until no conversation is running."] = "Welcher Anbieter gerade deine Gespräche beantwortet und, bei Convai, welcher Tarif sie bezahlt. Änderungen warten, bis kein Gespräch mehr läuft.",
    ["Who writes your companions’ replies. Convai is the default and the recommended choice, with better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech is recognized on this computer, so the voice key works. The change waits until no conversation is running; choose Apply."] = "Wer die Antworten deiner Begleiter schreibt. Convai ist die Standardeinstellung und die empfohlene Wahl, mit besserer Antwortqualität. Mistral nutzt seinen kostenlosen Tarif mit deinem eigenen kostenlosen Schlüssel (füge ihn unten hinzu; die Anmeldung braucht eine Telefonprüfung): die Erinnerungen bleiben auf diesem Computer, und der kostenlose Tarif erlaubt etwa eine Nachricht pro Sekunde und ein Monatskontingent. Eine Convai-Cloudstimme wird durch eine lokale Stimme ersetzt. Die Spracherkennung läuft auf diesem Computer, daher funktioniert die Sprachtaste. Die Änderung wartet, bis kein Gespräch mehr läuft; wähle Übernehmen.",
    ["Who writes your companions’ replies. Convai is the default and the recommended choice, with better quality responses. Mistral uses its free plan with your own free key (add it below; signing up needs phone verification): memory stays on this computer, and the free plan allows about one message a second and a monthly allowance. A Convai cloud voice is replaced by a local voice. Speech recognition for the voice key is not available yet with Mistral, so type your messages. The change waits until no conversation is running; choose Apply."] = "Wer die Antworten deiner Begleiter schreibt. Convai ist die Standardeinstellung und die empfohlene Wahl, mit besserer Antwortqualität. Mistral nutzt seinen kostenlosen Tarif mit deinem eigenen kostenlosen Schlüssel (füge ihn unten hinzu; die Anmeldung braucht eine Telefonprüfung): die Erinnerungen bleiben auf diesem Computer, und der kostenlose Tarif erlaubt etwa eine Nachricht pro Sekunde und ein Monatskontingent. Eine Convai-Cloudstimme wird durch eine lokale Stimme ersetzt. Die Spracherkennung für die Sprachtaste ist bei Mistral noch nicht verfügbar, daher tippe deine Nachrichten ein. Die Änderung wartet, bis kein Gespräch mehr läuft; wähle Übernehmen.",
}
